% SPDX-License-Identifier: EUPL-1.2
:- module(m__eu_data_act_connected_product_data_sharing_citations, [citation/2, implements/1]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

implements(Key) :-
    citation(Key, _).

citation(eu_reg_2023_2854_art_2_5, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 2, point (5), definition of connected product', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art2_5)', verbatim - 'means an item that obtains, generates or collects data concerning its use or environment and that is able to communicate product data via an electronic communications service, physical connection or on-device access, and whose primary function is not the storing, processing or transmission of data on behalf of any party other than the user;']).
citation(eu_reg_2023_2854_art_2_6, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 2, point (6), definition of related service', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art2_6)', verbatim - 'means a digital service, other than an electronic communications service, including software, which is connected with the product at the time of the purchase, rent or lease in such a way that its absence would prevent the connected product from performing one or more of its functions, or which is subsequently connected to the product by the manufacturer or a third party to add to, update or adapt the functions of the connected product;']).
citation(eu_reg_2023_2854_art_2_12, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 2, point (12), definition of user', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art2_12)', verbatim - 'means a natural or legal person that owns a connected product or to whom temporary rights to use that connected product have been contractually transferred, or that receives related services;']).
citation(eu_reg_2023_2854_art_2_13, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 2, point (13), definition of data holder', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art2_13)', verbatim - 'means a natural or legal person that has the right or obligation, in accordance with this Regulation, applicable Union law or national legislation adopted in accordance with Union law, to use and make available data, including, where contractually agreed, product data or related service data which it has retrieved or generated during the provision of a related service;']).
citation(eu_reg_2023_2854_art_2_15, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 2, point (15), definition of product data', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art2_15)', verbatim - 'means data generated by the use of a connected product that the manufacturer designed to be retrievable, via an electronic communications service, physical connection or on-device access, by a user, data holder or a third party, including, where relevant, the manufacturer;']).
citation(eu_reg_2023_2854_art_2_16, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 2, point (16), definition of related service data', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art2_16)', verbatim - 'means data representing the digitisation of user actions or of events related to the connected product, recorded intentionally by the user or generated as a by-product of the user’s action during the provision of a related service by the provider;']).
citation(eu_reg_2023_2854_art_2_17, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 2, point (17), definition of readily available data', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art2_17)', verbatim - 'means product data and related service data that a data holder lawfully obtains or can lawfully obtain from the connected product or related service, without disproportionate effort going beyond a simple operation;']).
citation(eu_reg_2023_2854_art_3_1, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(1), design duty (data accessible by default)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p1)', verbatim - 'Connected products shall be designed and manufactured, and related services shall be designed and provided, in such a manner that product data and related service data, including the relevant metadata necessary to interpret and use those data, are, by default, easily, securely, free of charge, in a comprehensive, structured, commonly used and machine-readable format, and, where relevant and technically feasible, directly accessible to the user.']).
citation(eu_reg_2023_2854_art_3_2, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(2), pre-contract information for the purchase, rent or lease of a connected product', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p2)', verbatim - 'Before concluding a contract for the purchase, rent or lease of a connected product, the seller, rentor or lessor, which may be the manufacturer, shall provide at least the following information to the user, in a clear and comprehensible manner:']).
citation(eu_reg_2023_2854_art_3_2_a, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(2), point (a), type, format and estimated volume of product data', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p2_a)', verbatim - 'the type, format and estimated volume of product data which the connected product is capable of generating;']).
citation(eu_reg_2023_2854_art_3_2_b, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(2), point (b), continuous and real-time generation', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p2_b)', verbatim - 'whether the connected product is capable of generating data continuously and in real-time;']).
citation(eu_reg_2023_2854_art_3_2_c, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(2), point (c), storage on-device or on a remote server and retention', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p2_c)', verbatim - 'whether the connected product is capable of storing data on-device or on a remote server, including, where applicable, the intended duration of retention;']).
citation(eu_reg_2023_2854_art_3_2_d, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(2), point (d), how the user may access, retrieve or erase the data', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p2_d)', verbatim - 'how the user may access, retrieve or, where relevant, erase the data, including the technical means to do so, as well as their terms of use and quality of service.']).
citation(eu_reg_2023_2854_art_3_3, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(3), pre-contract information for the provision of a related service', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p3)', verbatim - 'Before concluding a contract for the provision of a related service, the provider of such related service shall provide at least the following information to the user, in a clear and comprehensible manner:']).
citation(eu_reg_2023_2854_art_3_3_a, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(3), point (a), product data the prospective data holder is expected to obtain', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p3_a)', verbatim - 'the nature, estimated volume and collection frequency of product data that the prospective data holder is expected to obtain and, where relevant, the arrangements for the user to access or retrieve such data, including the prospective data holder’s data storage arrangements and the duration of retention;']).
citation(eu_reg_2023_2854_art_3_3_b, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(3), point (b), related service data to be generated', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p3_b)', verbatim - 'the nature and estimated volume of related service data to be generated, as well as the arrangements for the user to access or retrieve such data, including the prospective data holder’s data storage arrangements and the duration of retention;']).
citation(eu_reg_2023_2854_art_3_3_c, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(3), point (c), own use of readily available data and third-party use', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p3_c)', verbatim - 'whether the prospective data holder expects to use readily available data itself and the purposes for which those data are to be used, and whether it intends to allow one or more third parties to use the data for purposes agreed upon with the user;']).
citation(eu_reg_2023_2854_art_3_3_d, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(3), point (d), identity of the prospective data holder', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p3_d)', verbatim - 'the identity of the prospective data holder, such as its trading name and the geographical address at which it is established and, where applicable, of other data processing parties;']).
citation(eu_reg_2023_2854_art_3_3_e, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(3), point (e), means of communication with the prospective data holder', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p3_e)', verbatim - 'the means of communication which make it possible to contact the prospective data holder quickly and communicate with that data holder efficiently;']).
citation(eu_reg_2023_2854_art_3_3_f, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(3), point (f), how to request sharing with a third party and end it', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p3_f)', verbatim - 'how the user can request that the data are shared with a third party and, where applicable, end the data sharing;']).
citation(eu_reg_2023_2854_art_3_3_g, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(3), point (g), right to lodge a complaint', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p3_g)', verbatim - 'the user’s right to lodge a complaint alleging an infringement of any of the provisions of this Chapter with the competent authority designated pursuant to Article 37;']).
citation(eu_reg_2023_2854_art_3_3_h, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(3), point (h), trade secret holder', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p3_h)', verbatim - 'whether a prospective data holder is the holder of trade secrets contained in the data that is accessible from the connected product or generated during the provision of a related service, and, where the prospective data holder is not the trade secret holder, the identity of the trade secret holder;']).
citation(eu_reg_2023_2854_art_3_3_i, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 3(3), point (i), contract duration and termination', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art3_p3_i)', verbatim - 'the duration of the contract between the user and the prospective data holder, as well as the arrangements for terminating such a contract.']).
citation(eu_reg_2023_2854_art_4_1, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 4(1), access by the user to readily available data', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art4_p1)', verbatim - 'Where data cannot be directly accessed by the user from the connected product or related service, data holders shall make readily available data, as well as the relevant metadata necessary to interpret and use those data, accessible to the user without undue delay, of the same quality as is available to the data holder, easily, securely, free of charge, in a comprehensive, structured, commonly used and machine-readable format and, where relevant and technically feasible, continuously and in real-time. This shall be done on the basis of a simple request through electronic means where technically feasible.']).
citation(eu_reg_2023_2854_art_4_2, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 4(2), contractual security restriction', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art4_p2)', verbatim - 'Users and data holders may contractually restrict or prohibit accessing, using or further sharing data, if such processing could undermine security requirements of the connected product, as laid down by Union or national law, resulting in a serious adverse effect on the health, safety or security of natural persons.']).
citation(eu_reg_2023_2854_art_4_6, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 4(6), trade secrets preserved and identified', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art4_p6)', verbatim - 'Trade secrets shall be preserved and shall be disclosed only where the data holder and the user take all necessary measures prior to the disclosure to preserve their confidentiality in particular regarding third parties.']).
citation(eu_reg_2023_2854_art_4_7, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 4(7), first sentence, withholding trade secrets from the user', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art4_p7)', verbatim - 'Where there is no agreement on the necessary measures referred to in paragraph 6, or if the user fails to implement the measures agreed pursuant to paragraph 6 or undermines the confidentiality of the trade secrets, the data holder may withhold or, as the case may be, suspend the sharing of data identified as trade secrets.']).
citation(eu_reg_2023_2854_art_4_8, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 4(8), first sentence, refusal in exceptional circumstances (user)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art4_p8)', verbatim - 'In exceptional circumstances, where the data holder who is a trade secret holder is able to demonstrate that it is highly likely to suffer serious economic damage from the disclosure of trade secrets, despite the technical and organisational measures taken by the user pursuant to paragraph 6 of this Article, that data holder may refuse on a case-by-case basis a request for access to the specific data in question.']).
citation(eu_reg_2023_2854_art_4_12, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 4(12), personal data of another data subject made available to the user', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art4_p12)', verbatim - 'Where the user is not the data subject whose personal data is requested, any personal data generated by the use of a connected product or related service shall be made available by the data holder to the user only where there is a valid legal basis for processing under Article 6 of Regulation (EU) 2016/679 and, where relevant, the conditions of Article 9 of that Regulation and of Article 5(3) of Directive 2002/58/EC are fulfilled.']).
citation(eu_reg_2023_2854_art_5_1, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 5(1), making readily available data available to a third party', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art5_p1)', verbatim - 'Upon request by a user, or by a party acting on behalf of a user, the data holder shall make available readily available data, as well as the relevant metadata necessary to interpret and use those data, to a third party without undue delay, of the same quality as is available to the data holder, easily, securely, free of charge to the user, in a comprehensive, structured, commonly used and machine-readable format and, where relevant and technically feasible, continuously and in real-time.']).
citation(eu_reg_2023_2854_art_5_2, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 5(2), testing data of products not yet placed on the market', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art5_p2)', verbatim - 'Paragraph 1 shall not apply to readily available data in the context of the testing of new connected products, substances or processes that are not yet placed on the market unless their use by a third party is contractually permitted.']).
citation(eu_reg_2023_2854_art_5_3, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 5(3), designated gatekeeper not an eligible third party', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art5_p3)', verbatim - 'Any undertaking designated as a gatekeeper, pursuant to Article 3 of Regulation (EU) 2022/1925, shall not be an eligible third party under this Article']).
citation(eu_reg_2023_2854_art_5_7, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 5(7), personal data of another data subject made available to the third party', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art5_p7)', verbatim - 'Where the user is not the data subject whose personal data is requested, any personal data generated by the use of a connected product or related service shall be made available by the data holder to the third party only where there is a valid legal basis for processing under Article 6 of Regulation (EU) 2016/679 and, where relevant, the conditions of Article 9 of that Regulation and of Article 5(3) of Directive 2002/58/EC are fulfilled.']).
citation(eu_reg_2023_2854_art_5_9, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 5(9), trade secrets disclosed to third parties only as strictly necessary', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art5_p9)', verbatim - 'Trade secrets shall be preserved and shall be disclosed to third parties only to the extent that such disclosure is strictly necessary to fulfil the purpose agreed between the user and the third party.']).
citation(eu_reg_2023_2854_art_5_10, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 5(10), first sentence, withholding trade secrets from the third party', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art5_p10)', verbatim - 'Where there is no agreement on the necessary measures referred to in paragraph 9 of this Article or if the third party fails to implement the measures agreed pursuant to paragraph 9 of this Article or undermines the confidentiality of the trade secrets, the data holder may withhold or, as the case may be, suspend the sharing of data identified as trade secrets.']).
citation(eu_reg_2023_2854_art_5_11, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 5(11), first sentence, refusal in exceptional circumstances (third party)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art5_p11)', verbatim - 'In exceptional circumstances, where the data holder who is a trade secret holder is able to demonstrate that it is highly likely to suffer serious economic damage from the disclosure of trade secrets, despite the technical and organisational measures taken by the third party pursuant to paragraph 9 of this Article, that data holder may refuse on a case-by-case basis a request for access to the specific data in question.']).
citation(eu_reg_2023_2854_art_7_1, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 7(1), first subparagraph, micro and small enterprise exemption', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art7_p1)', verbatim - 'The obligations of this Chapter shall not apply to data generated through the use of connected products manufactured or designed or related services provided by a microenterprise or a small enterprise, provided that that enterprise does not have a partner enterprise or a linked enterprise within the meaning of Article 3 of the Annex to Recommendation 2003/361/EC that does not qualify as a microenterprise or a small enterprise and where the microenterprise and small enterprise is not subcontracted to manufacture or design a connected product or to provide a related service.']).
citation(eu_reg_2023_2854_art_7_t1, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 7(1), second subparagraph, recently medium-sized enterprises and products', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art7_t1)', verbatim - 'The same shall apply to data generated through the use of connected products manufactured by or related services provided by an enterprise that has qualified as a medium-sized enterprise under Article 2 of the Annex to Recommendation 2003/361/EC for less than one year and to connected products for one year after the date on which they were placed on the market by a medium-sized enterprise.']).
citation(eu_reg_2023_2854_art_50_t2, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 50, second paragraph, application from 12 September 2025', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art50_t2)', verbatim - 'It shall apply from 12 September 2025.']).
citation(eu_reg_2023_2854_art_50_t3, [label - 'Regulation (EU) 2023/2854 (Data Act) Art 50, third paragraph, application of Art 3(1) to products placed on the market after 12 September 2026', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32023R2854 (unit 32023R2854#art50_t3)', verbatim - 'The obligation resulting from Article 3(1) shall apply to connected products and the services related to them placed on the market after 12 September 2026.']).
